class Solution:
    def getPermutation(self, n: int, k: int) -> str:
        nums = [str(i) for i in range(1, n + 1)]
        fact = 1
        for i in range(1, n):
            fact *= i
        k -= 1
        res = []
        for i in range(n - 1, 0, -1):
            idx = k // fact
            res.append(nums.pop(idx))
            k %= fact
            fact //= i
        res.append(nums[0])
        return "".join(res)

