class Solution {
    public String getPermutation(int n, int k) {
        List<Integer> nums = new ArrayList<>();
        int fact = 1;
        for (int i = 1; i <= n; i++) {
            nums.add(i);
            if (i < n) fact *= i;
        }
        k--;
        StringBuilder sb = new StringBuilder();
        for (int i = n - 1; i >= 1; i--) {
            int idx = k / fact;
            sb.append(nums.get(idx));
            nums.remove(idx);
            k %= fact;
            fact /= i;
        }
        sb.append(nums.get(0));
        return sb.toString();
    }
}

var getPermutation = function(n, k) {
    const nums = [];
    let fact = 1;
    for (let i = 1; i <= n; i++) {
        nums.push(i);
        if (i < n) fact *= i;
    }
    k--;
    let res = "";
    for (let i = n - 1; i >= 1; i--) {
        const idx = Math.floor(k / fact);
        res += nums[idx];
        nums.splice(idx, 1);
        k %= fact;
        fact = Math.floor(fact / i);
    }
    res += nums[0];
    return res;
};
